/* ===== V127: سبب الخصم (مؤثر، ضيافة، موظف، تعويض) + تقرير المجاني ===== */
const DIS_WHY=['عادي','مؤثر','ضيافة','موظف','تعويض'];
let disWhy='عادي';
function disUi(){
  const w=document.getElementById('disWhyRow'); if(!w) return;
  const dis=+document.getElementById('fDiscount').value||0; w.hidden=!dis;
  w.querySelectorAll('[data-w]').forEach(b=>b.classList.toggle('on',b.dataset.w===disWhy));
  document.getElementById('disWhoWrap').hidden=!(dis&&disWhy==='مؤثر');
}
document.getElementById('disWhyRow').addEventListener('click',e=>{ const b=e.target.closest('[data-w]'); if(!b) return; disWhy=b.dataset.w; disUi(); if(disWhy==='مؤثر') setTimeout(()=>{ try{ document.getElementById('disWho').focus() }catch(_){} },30) });
document.getElementById('disFreeBtn').addEventListener('click',()=>{
  const sub=cart.reduce((s,c)=>s+c.price*c.qty,0), del=+document.getElementById('fDelivery').value||0;
  if(!sub){ toast('ضيف الأصناف أول'); return }
  document.getElementById('fDiscount').value=sub+del; if(disWhy==='عادي') disWhy='مؤثر'; calc(); disUi();
});
function disLabel(o){ if(!o.dis) return ''; const w=o.disWhy||'بدون سبب'; return w+(o.disWho?' · '+o.disWho:'') }
function disReport(R){
  const el=document.getElementById('repDis'); if(!el) return;
  const L=R.ok.filter(o=>o.dis>0); if(!L.length){ el.innerHTML='<div class="hint">ماكو خصومات بهالفترة</div>'; return }
  const by={}; L.forEach(o=>{ const k=o.disWhy||'بدون سبب'; const b=by[k]||(by[k]={n:0,v:0,free:0}); b.n++; b.v+=o.dis; if(!o.total) b.free++ });
  const inf={}; L.filter(o=>o.disWhy==='مؤثر').forEach(o=>{ const k=o.disWho||'بدون اسم'; const b=inf[k]||(inf[k]={n:0,v:0}); b.n++; b.v+=o.dis });
  const free=L.filter(o=>!o.total), fv=free.reduce((s,o)=>s+o.dis,0);
  el.innerHTML=`<div class="dis-sum"><b>${fmt(fv)} د.ع</b><span>انطيتوا مجاناً بـ ${fmt(free.length)} طلب</span></div>
    <table class="rt"><thead><tr><th>السبب</th><th>طلبات</th><th>منها مجاني</th><th>قيمة الخصم</th></tr></thead><tbody>`+
    Object.keys(by).sort((a,b)=>by[b].v-by[a].v).map(k=>`<tr><td>${esc(k)}</td><td>${fmt(by[k].n)}</td><td>${fmt(by[k].free)}</td><td>${fmt(by[k].v)}</td></tr>`).join('')+`</tbody></table>`+
    (Object.keys(inf).length?`<h4 style="margin:14px 0 6px">المؤثرين</h4><table class="rt"><thead><tr><th>المؤثر</th><th>طلبات</th><th>القيمة</th></tr></thead><tbody>`+Object.keys(inf).sort((a,b)=>inf[b].v-inf[a].v).map(k=>`<tr><td>${esc(k)}</td><td>${fmt(inf[k].n)}</td><td>${fmt(inf[k].v)}</td></tr>`).join('')+`</tbody></table>`:'');
}
  ov.querySelectorAll('[data-ow]').forEach(b=>b.addEventListener('click',()=>{ o.disWhy=b.dataset.ow; ov.querySelectorAll('[data-ow]').forEach(x=>x.classList.toggle('on',x===b)); saveAll(); toast('انحفظ السبب: '+o.disWhy) }));
  { const wi=ov.querySelector('.od-who'); if(wi) wi.addEventListener('change',()=>{ o.disWho=wi.value.trim(); if(o.disWho&&!o.disWhy) o.disWhy='مؤثر'; saveAll(); toast('انحفظ') }) }
    <div class="od-sec">${row('قيمة الأكل',fmt(o.sub||0)+' د.ع')}${row('أجرة التوصيل',fmt(o.del||0)+' د.ع')}${o.dis?row('الخصم','− '+fmt(o.dis)+' د.ع'+(o.total?'':' (مجاني)'),'od-dis'):''}${o.dis?`<div class="od-r"><span>سبب الخصم</span><span class="dw-chips od-why">${['عادي','مؤثر','ضيافة','موظف','تعويض'].map(w=>`<button type="button" data-ow="${w}" class="${(o.disWhy||'')===w?'on':''}">${w}</button>`).join('')}</span></div><div class="od-r"><span>المؤثر</span><span><input class="od-who" value="${esc(o.disWho||'')}" placeholder="الاسم أو الحساب"></span></div>`:''}${row('المجموع',fmt(o.total||0)+' د.ع','od-tot')}</div>
  try{ disReport(R) }catch(_){}
      <span class="ototal">${fmt(o.total)} د.ع${o.dis?`<small class="odis">${o.total?'خصم '+fmt(o.dis):'مجاني'}${o.disWhy&&o.disWhy!=='عادي'?' · '+esc(o.disWhy)+(o.disWho?' '+esc(o.disWho):''):''}</small>`:''}</span>
  document.getElementById('fDiscount').value=0; disWhy='عادي'; { const dw=document.getElementById('disWho'); if(dw) dw.value='' }
  if(dis){ o.disWhy=disWhy; const dw=(document.getElementById('disWho')||{}).value; if(disWhy==='مؤثر'&&dw&&dw.trim()) o.disWho=dw.trim() }
  nextNumUi(); livePreview(); try{ disUi() }catch(_){}
const SAFI_VER='V127';
    <div class="card"><h3>الأصناف الأكثر بيعاً</h3><div id="repItems"></div><h3 style="margin-top:18px">حسب نوع الطلب</h3><div class="rep-types" id="repTypes"></div><h3 style="margin-top:18px">الخصومات والمجاني</h3><div id="repDis"></div></div>
      <div class="dis-why" id="disWhyRow" hidden><span>سبب الخصم</span><div class="dw-chips"><button type="button" data-w="عادي">عادي</button><button type="button" data-w="مؤثر">مؤثر</button><button type="button" data-w="ضيافة">ضيافة</button><button type="button" data-w="موظف">موظف</button><button type="button" data-w="تعويض">تعويض</button></div>
        <label class="tf" id="disWhoWrap" hidden><span>اسم أو حساب المؤثر</span><input id="disWho" type="text" placeholder="مثلاً @basra_food"></label></div>
      <button type="button" class="dis-free" id="disFreeBtn">مجاني بالكامل (مؤثر / ضيافة)</button>
.dis-why{grid-column:1/-1;display:grid;gap:6px}
.dis-why>span{font-size:13px;color:#9296A0}
.dw-chips{display:flex;flex-wrap:wrap;gap:6px}
.dw-chips button{min-height:36px;padding:0 12px;border-radius:999px;border:1px solid var(--line2,#2a2c33);background:transparent;color:#C9CCD3;font:inherit;font-size:13.5px;cursor:pointer}
.dw-chips button.on{background:#F5C04A;color:#111;border-color:#F5C04A;font-weight:700}
.dis-free{grid-column:1/-1;min-height:40px;border-radius:10px;border:1px dashed #F5C04A;background:transparent;color:#F5C04A;font:inherit;font-size:14px;cursor:pointer}
.od-why button{min-height:32px;padding:0 10px;font-size:12.5px}
.od-who{min-height:36px;max-width:200px}
.dis-sum{display:flex;align-items:baseline;gap:10px;padding:12px 14px;border-radius:12px;background:rgba(245,192,74,.1);margin-bottom:10px}
.dis-sum b{font-size:22px;color:#F5C04A}.dis-sum span{color:#C9CCD3;font-size:14px}
